    if isinstance(o,dict):
        return '{'+','.join(json.dumps(k,ensure_ascii=False)+':'+canon(v) for k,v in sorted(o.items()))+'}'
    if isinstance(o,list):
        return '['+','.join(canon(v) for v in o)+']'
