    if isinstance(o,list):
        return '['+','.join(canon2(v) for v in o)+']'
    return json.dumps(o,separators=(',',':'))
print('sorted-ascii',hashlib.sha256(canon2(c).encode()).hexdigest())
print(json.dumps(sorted(c.keys())))
