import json
p=json.load(open('package.json'))
ex=p['exports']
for k,v in ex.items():
    bound = v if isinstance(v,dict) else {'default':v}
    vals=[s for s in bound.values() if isinstance(s,str)]
    if any(re_ := (True for s in vals if 'agent-runtime' in s or 'plugin-sdk' in s)) and any('runtime' in k or 'agent' in k for k in [k]):
        pass
" 2>/dev/null; node -e "
const p=require('./package.json');
const ex=p.exports;
for (const [k,v] of Object.entries(ex)) {
  const b = (typeof v!=='object')?{default:v}:v;
  const vals=Object.values(b).filter(x=>typeof x==='string');
  if (vals.some(v2=>/plugin-sdk|root|\.d\.ts/.test(v2))===false) continue;
  if (/^\\.(\\/(plugin-sdk\\/(agent|skill|runtime))|$|\\/(agent-runtime|openclaw))/.test(k) || /plugin-sdk/.test(k)) {
    console.log(k, JSON.stringify(b));
  }
}
" | head -60"}

