cd /home/just_dak/projects/relaymind/docs/evidence/m10 && python3 - <<'EOF'
import json
for f in ['openclaw-loaded-use-observation-20261101-ci.json','openclaw-loaded-use-observation-20261101-vps2.json','openclaw-loaded-use-observation-20261101-vps.json']:
    c=json.load(open(f))
    print('=====',f)
    print('keys:',sorted(c.keys()))
    for k in ('kind','host_version','status','fixture','phase','tier','qualification'):
        if k in c: print(k,':',c[k])
    slu=c.get('ordinary_skill_loaded_use') or c.get('skill_loaded_use') or {}
    for case in slu.get('cases',[]):
        print(' case',case.get('case'),'intervention',case.get('intervention'),'observed',case.get('observed'),
              'n_requests',len(case.get('requests',[])),
              'terminal', (case.get('terminal') or {}).get('state'))
        sel=case.get('selected') or {}
        if sel: print('   selected.rev',sel.get('revision'),'content_sha',sel.get('content_sha256'))
        loaded=case.get('loaded') or case.get('observed_payload') or None
    print(' slu keys:', list(slu.keys()))
EOF

