let hits=[];
for (const [k,v] of Object.entries(ex)) {
  const s=JSON.stringify(v);
  if (/admitted-run|run-admission|embedded-agent|runtime-embedded/.test(s)) hits.push(k+' -> '+s);
}
console.log(hits.join('\n')||'NO public export path to admitted-run/run-admission modules');
"

